<x-layouts::app title="KPI templates"><x-workspace-command-bar title="KPI templates" icon="fa-bullseye"><x-slot:actions><button class="btn btn-action-link btn-sm" data-bs-toggle="modal" data-bs-target="#addTemplate"><i class="fa-solid fa-circle-plus"></i><span>Add template</span></button></x-slot:actions></x-workspace-command-bar>@if(session('status'))<div class="alert alert-success">{{ session('status') }}</div>@endif @if($errors->any())<div class="alert alert-danger">{{ $errors->first() }}</div>@endif<div class="reference-list"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th class="ps-3">Template</th><th>Position</th><th>Frequency</th><th>Criteria</th><th>Status</th></tr></thead><tbody>@forelse($templates as $template)<tr><td class="ps-3 fw-medium">{{ $template->name }}</td><td>{{ $template->position?->title ?: 'All positions' }}</td><td>{{ str($template->review_frequency)->title() }}</td><td>{{ $template->items->count() }} · {{ number_format($template->items->sum('weight'), 0) }}%</td><td><span class="badge text-bg-{{ $template->is_active ? 'success':'secondary' }}">{{ $template->is_active ? 'Active':'Inactive' }}</span></td></tr>@empty<tr><td colspan="5" class="text-center py-5">No KPI templates.</td></tr>@endforelse</tbody></table></div><x-pagination-footer :paginator="$templates" /></div><div class="modal fade" id="addTemplate"><div class="modal-dialog modal-xl"><form class="modal-content" method="POST" action="{{ route('performance.kpi-templates.store') }}">@csrf<div class="modal-header"><h2 class="modal-title fs-5">Add KPI template</h2><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-6"><label class="form-label">Name <span class="text-danger">*</span></label><input class="form-control" name="name" required></div><div class="col-md-3"><label class="form-label">Position</label><select class="form-select" name="position_id"><option value="">All positions</option>@foreach($positions as $position)<option value="{{ $position->id }}">{{ $position->title }}{{ $position->department?->name ? ' — '.$position->department->name : '' }}{{ $position->branch?->name ? ' / '.$position->branch->name : '' }}</option>@endforeach</select></div><div class="col-md-3"><label class="form-label">Frequency</label><select class="form-select" name="review_frequency"><option>monthly</option><option>quarterly</option><option>semiannual</option><option>annual</option></select></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description"></textarea></div></div><h3 class="h6 mt-4">Criteria (weights must total 100%)</h3>@foreach([0,1,2] as $i)<div class="row g-2 mb-2"><div class="col-5"><input class="form-control" name="items[{{ $i }}][name]" placeholder="Criterion {{ $i+1 }}" {{ $i===0?'required':'' }}></div><div class="col-3"><input class="form-control" name="items[{{ $i }}][measurement_unit]" placeholder="Unit" {{ $i===0?'required':'' }}></div><div class="col-2"><input class="form-control" type="number" step=".01" name="items[{{ $i }}][target_value]" placeholder="Target" {{ $i===0?'required':'' }}></div><div class="col-2"><input class="form-control" type="number" step=".01" name="items[{{ $i }}][weight]" placeholder="Weight %" {{ $i===0?'required':'' }}></div></div>@endforeach</div><x-form-save-actions save-label="Save & close" /></form></div></div></x-layouts::app>
